def discard(self, n=-1, qid=-1, dehydration_hooks=None, hydration_hooks=None, **handlers):
    try:
        if n == -1:
            n = len(self._output)
        if qid == -1:
            qid = self._last_query
        if not 0 <= n <= len(self._output):
            raise ValueError("Invalid number of records to discard")
        if n == 0:
            # Nothing to discard
            return
        # Discard the first n records
        self._output = self._output[n:]
        # Update the last query ID
        self._last_query = qid
        # Return a Response object
        return Response(dehydration_hooks=dehydration_hooks, hydration_hooks=hydration_hooks, handlers=handlers)
    except Exception as e:
        # Handle any exception
        print(f"Error: {e}")

