    try:
        with open(file_name, "ab" if overwrite else "a", encoding=encoding) as file_handle:
            file_handle.write(text_buffer)
    except FileNotFoundError:
        try:
            with open(file_name, "xb", encoding=encoding) as file_handle:
                file_handle.write(text_buffer)
        except FileExistsError:
            return len(text_buffer)
        except:
            return -1
    except Exception as e:
        return -1
    return len(text_buffer)

