def _normalizeargs(sequence, output=None):
    # Normalize declaration arguments
    # Normalization arguments might contain Declarions, tuples, or single interfaces.
    # Anything but individial interfaces or implements specs will be expanded.
    expanded = set()
    for interface in sequence:
        if isinstance(interface, tuple):
            expanded.update(interface)
        elif isinstance(interface, Declaration):
            expanded.add(interface)
    if output is not None:
        if not isinstance(output, list):
            raise TypeError("output must be a list")
        output.extend(expanded)
        return output
    else:
        return list(expanded)

