def validate_as_prior_version(self, prior):
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    if self.parent is None or prior.parent is None:
        raise ValueError("Both self and prior must have a valid parent inventory")
    if self.parent.name != prior.parent.name:
        raise ValueError("Parent inventories must have the same name")
    if self.name != prior.name:
        raise ValueError("Inventory names must be the same")
    if self.id != prior.id:
        raise ValueError("Inventory IDs must be the same")
    for sku, stock_dict in self.stocks.items():
        if sku not in prior.stocks:
            raise ValueError("SKU {} is not in prior".format(sku))
        prior_stock_dict = prior.stocks[sku]
        for loc, count in stock_dict.items():
            if loc not in prior_stock_dict or prior_stock_dict[loc] != count:
                raise ValueError("Count for SKU {} in location {} does not match prior".format(sku, loc))
        for loc in prior_stock_dict:
            if loc not in stock_dict:
                raise ValueError("Location {} does not have a count in prior".format(loc))
    return True

