def get_logical_path_map(inventory, version):
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary.")
    if not isinstance(version, str):
        raise ValueError("Version must be a string.")
    if version not in inventory:
        raise ValueError(f"Version {version} not found in inventory.")

    logical_path_map = {}
    for version, files in inventory.items():
        if version == inventory:
            for logical_path_in_state, content_files in files.items():
                if logical_path_map.get(logical_path_in_state):
                    logical_path_map[logical_path_in_state].update(content_files)
                else:
                    logical_path_map[logical_path_in_state] = set(content_files)
    return logical_path_map

