def _verify(iface, candidate, tentative=False, vtype=None):
    try:
        if tentative:
            return True

        provided_by = iface.__providedBy__(candidate)
        if not provided_by:
            raise ValueError("Candidate does not provided interface")

        necessary_methods, necessary_attributes = _verify_interface(iface)
        invalid_methods = []
        invalid_attributes = []

        for method in necessary_methods:
            if not hasattr(candidate, method):
                invalid_methods.append(method)

        for attribute in necessary_attributes:
            if not hasattr(candidate, attribute):
                invalid_attributes.append(attribute)

        if invalid_methods:
            required_methods_str = ", ".join(necessary_methods)
            raise ValueError(f"Candidate does not define all required methods: {required_methods_str}")

        if invalid_attributes:
            required_attributes_str = ", ".join(necessary_attributes)
