def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        # If explicit metaclass is provided, return it
        return explicit_mc
    if len(bases) == 0:
        # If no bases are provided, create a new metaclass based on the defining class type
        return type(bases[0])
    else:
        # If bases are provided, determine the most-derived metaclass using C3 MRO
        mros = [type(b).__mro__ for b in bases]
        return type(functools.reduce(lambda x, y: next(z for z in x if z in y), itertools.product(*mros)))

