def fromutc(self, dt):
    try:
        tzu = dt.tzinfo.utcoffset(dt)
        tzu = tzu.total_seconds()
        dto = dt.toordinal()
        h,m,s = dt.hour, dt.minute, dt.second
        microsecond = dt.microsecond
        if dt.tzinfo._utc_transition_times[dto] == (h,m,s,microsecond):
            return self.fromutc(dt.replace(tzinfo=None))
        dt = dt.replace(tzinfo=self)
        dt += timedelta(seconds=tzu)
        return dt
    except Exception as e:
        raise e

