def verify_relayable_signature(public_key, doc, signature):

    try:
        public_key = int(public_key)
        doc = int(doc)
        signature = int(signature)
    except ValueError:
        raise ValueError("Illegal argument: not an integer")

    # Check that the signature is valid
    if not signature:
        return False

    # Check that the public key is valid
    if not public_key:
        return False

    # Verify the signature using the public key and the document
    if (signature * public_key) % doc:
        return False

    # The signature is valid
    return True

