    try:
        # Make sure the workspace is valid
        if ir_workspace is None or ir_workspace.is_valid() is False:
            raise ValueError("Invalid Infrared Workspace")

        # Make sure the plugin is valid
        if ir_plugin is None or ir_plugin.is_valid() is False:
            raise ValueError("Invalid Infrared Plugin")

        # Make sure the playbook path is valid
        if playbook_path is None or os.path.isfile(playbook_path) is False:
            raise ValueError("Invalid playbook path")

        # Build the Ansible command line arguments
        ansible_cmd_args = [
            "ansible-playbook",
            playbook_path,
            "-w" + f"{ir_workspace.id}",
            "-p" + f"{ir_plugin.id}"
        ]

        # Add extra vars if provided
        if extra_vars is not None:
            ansible_cmd_args.append("--extra-vars")
            ansible_cmd_args.append(extra_vars)

        # Add Ansible args if provided
        if ansible_args is not None:
            for ansible_arg in ansible_args:
                ansible_cmd_args.append(ansible_arg)

        # Run the Ansible command
        return subprocess.check_output(ansible_cmd_args)

    except Exception as e:
        raise RuntimeError("Failed to run Ansible playbook: " + str(e)) from None

